<?php
require 'db.php';$me=user();$cart=$_SESSION['cart']??[];$error='';
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['checkout'])){require_role(['Customer']);check_csrf();$cart=$_SESSION['cart']??[];$address=trim($_POST['address']??'');$note=trim($_POST['note']??'');if(!$cart)$error='Your cart is empty.';elseif(strlen($address)<8)$error='Enter a full delivery address.';else{$ids=array_map('intval',array_keys($cart));$marks=implode(',',array_fill(0,count($ids),'?'));$types=str_repeat('i',count($ids));$s=$conn->prepare("SELECT m.id,m.name,m.price,m.stock,m.restaurant_id,r.delivery_fee FROM menu_items m JOIN restaurants r ON r.id=m.restaurant_id WHERE m.id IN ($marks) FOR UPDATE");$conn->begin_transaction();$s->bind_param($types,...$ids);$s->execute();$rs=$s->get_result();$rows=[];$subtotal=0;$restaurant=0;$fee=0;while($m=$rs->fetch_assoc()){$qty=(int)$cart[$m['id']]['quantity'];if($qty<1||$m['stock']<$qty){$error='An item in your cart no longer has enough stock.';break;}if($restaurant&&(int)$m['restaurant_id']!==$restaurant){$error='A cart must contain items from one restaurant.';break;}$restaurant=(int)$m['restaurant_id'];$fee=(float)$m['delivery_fee'];$subtotal+=(float)$m['price']*$qty;$rows[]=[$m,$qty];}if(!$error&&count($rows)===count($cart)){$total=$subtotal+$fee;$payment='Cash';$paystatus='Cash due';$ins=$conn->prepare("INSERT INTO orders(customer_id,restaurant_id,status,subtotal,delivery_fee,total,payment_method,payment_status,delivery_address,customer_note) VALUES(?,?,'Placed',?,?,?,?,?,?,?)");$ins->bind_param('iidddssss',$me['id'],$restaurant,$subtotal,$fee,$total,$payment,$paystatus,$address,$note);if($ins->execute()){$oid=$conn->insert_id;$oi=$conn->prepare('INSERT INTO order_items(order_id,menu_item_id,item_name,unit_price,quantity) VALUES(?,?,?,?,?)');$st=$conn->prepare('UPDATE menu_items SET stock=stock-? WHERE id=? AND stock>=?');foreach($rows as [$m,$qty]){$oi->bind_param('iisdi',$oid,$m['id'],$m['name'],$m['price'],$qty);$oi->execute();$st->bind_param('iii',$qty,$m['id'],$qty);$st->execute();}$hist=$conn->prepare('INSERT INTO order_status_history(order_id,status,changed_by) VALUES(?,?,?)');$placed='Placed';$hist->bind_param('isi',$oid,$placed,$me['id']);$hist->execute();$conn->commit();unset($_SESSION['cart']);flash('Order #'.$oid.' placed. Pay cash on delivery.');header('Location: orders.php');exit;}else$error='Could not create the order.';}else $conn->rollback();}}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['update_status'])){require_role(['Restaurant','Admin']);check_csrf();$oid=(int)$_POST['order_id'];$status=$_POST['status'];$allowed=['Accepted','Preparing','Ready for pickup','Cancelled'];$sql='UPDATE orders o JOIN restaurants r ON r.id=o.restaurant_id SET o.status=? WHERE o.id=? AND '.($me['role']==='Admin'?'1=1':'r.owner_user_id=?').' AND o.status IN (\'Placed\',\'Accepted\',\'Preparing\',\'Ready for pickup\')';if(in_array($status,$allowed,true)){$s=$conn->prepare($sql);if($me['role']==='Admin')$s->bind_param('si',$status,$oid);else $s->bind_param('sii',$status,$oid,$me['id']);$s->execute();if($s->affected_rows){$hist=$conn->prepare('INSERT INTO order_status_history(order_id,status,changed_by) VALUES(?,?,?)');$hist->bind_param('isi',$oid,$status,$me['id']);$hist->execute();flash('Order status updated.');}}header('Location: orders.php');exit;}
$orders=[];if($me){if($me['role']==='Admin'){$filter='1=1';}elseif($me['role']==='Restaurant'){$filter='o.restaurant_id IN (SELECT id FROM restaurants WHERE owner_user_id=?)';}else{$filter='o.customer_id=?';}$sql='SELECT o.*,r.name restaurant FROM orders o JOIN restaurants r ON r.id=o.restaurant_id WHERE '. $filter . ' ORDER BY o.created_at DESC';$s=$conn->prepare($sql);if($me['role']!=='Admin')$s->bind_param('i',$me['id']);$s->execute();$res=$s->get_result();while($o=$res->fetch_assoc()){$it=$conn->prepare('SELECT item_name,unit_price,quantity FROM order_items WHERE order_id=?');$it->bind_param('i',$o['id']);$it->execute();$o['items']=$it->get_result()->fetch_all(MYSQLI_ASSOC);$hist=$conn->prepare('SELECT status,created_at FROM order_status_history WHERE order_id=? ORDER BY id');$hist->bind_param('i',$o['id']);$hist->execute();$o['history']=$hist->get_result()->fetch_all(MYSQLI_ASSOC);$loc=$conn->prepare('SELECT latitude,longitude,recorded_at FROM delivery_locations WHERE order_id=? ORDER BY recorded_at DESC LIMIT 1');$loc->bind_param('i',$o['id']);$loc->execute();$o['location']=$loc->get_result()->fetch_assoc();$orders[]=$o;}}
page_start('Your orders');$msg=take_flash();if($msg)echo '<p class="pill">'.h($msg).'</p>';if(!$me):?><section class="hero"><h1>Your cart and order tracking</h1><p>Sign in to check out and follow your delivery.</p><a class="btn" href="login.php">Sign in</a></section><?php elseif($me['role']==='Customer'&&$cart):$ids=array_map('intval',array_keys($cart));$marks=implode(',',array_fill(0,count($ids),'?'));$s=$conn->prepare("SELECT m.id,m.name,m.price,m.stock,r.name restaurant,r.delivery_fee FROM menu_items m JOIN restaurants r ON r.id=m.restaurant_id WHERE m.id IN ($marks)");$t=str_repeat('i',count($ids));$s->bind_param($t,...$ids);$s->execute();$res=$s->get_result();$total=0;$items=[];while($m=$res->fetch_assoc()){$qty=$cart[$m['id']]['quantity'];$total+=$m['price']*$qty;$items[]=$m;}?><section class="hero"><h1>Your cart</h1><?php if($items):?><p class="muted">From <?=h($items[0]['restaurant'])?></p><?php foreach($items as $m):?><div class="row"><span><?=h($m['name'])?> × <?=$cart[$m['id']]['quantity']?></span><strong><?=number_format($m['price']*$cart[$m['id']]['quantity'],0)?> ₫</strong></div><?php endforeach;?><hr><div class="row"><strong>Estimated total (incl. delivery)</strong><strong><?=number_format($total+$items[0]['delivery_fee'],0)?> ₫</strong></div><form method="post" style="max-width:600px;margin-top:20px"><?php csrf_field();?><label>Delivery address</label><input class="field" name="address" required minlength="8"><label>Note for restaurant or courier (optional)</label><textarea class="field" name="note"></textarea><p class="muted">Payment: cash on delivery. Online payment sandbox credentials are not configured.</p><?php if($error):?><p class="pill"><?=h($error)?></p><?php endif;?><button name="checkout">Place order</button></form><?php endif;?></section><?php endif;?><h1><?=($me&&$me['role']==='Admin')?'All orders':'Order history'?></h1><?php foreach($orders as $o):?><article class="card" style="margin-bottom:16px"><div class="row"><h2>Order #<?=$o['id']?> · <?=h($o['restaurant'])?></h2><span class="pill"><?=h($o['status'])?></span></div><p class="muted">Placed <?=h($o['created_at'])?> · <?=h($o['delivery_address'])?></p><?php foreach($o['items'] as $it):?><div><?=h($it['item_name'])?> × <?=$it['quantity']?> — <?=number_format($it['unit_price']*$it['quantity'],0)?> ₫</div><?php endforeach;?><p><strong>Total <?=number_format($o['total'],0)?> ₫</strong> · <?=h($o['payment_status'])?></p><div style="display:flex;gap:8px;flex-wrap:wrap"><?php foreach($o['history'] as $step):?><span class="pill"><?=h($step['status'])?> · <?=h($step['created_at'])?></span><?php endforeach;?></div><?php if(!empty($o["location"])):?><p>Courier GPS updated <?=h($o["location"]["recorded_at"])?> · <a target="_blank" rel="noopener" href="https://www.google.com/maps?q=<?=urlencode($o["location"]["latitude"].",".$o["location"]["longitude"])?>">View latest location</a></p><?php endif;?><?php if($me&&in_array($me['role'],['Restaurant','Admin'],true)):?><form method="post" style="margin-top:14px"><?php csrf_field();?><input type="hidden" name="order_id" value="<?=$o['id']?>"><select class="field" name="status"><?php foreach(['Accepted','Preparing','Ready for pickup','Cancelled'] as $v):?><option><?=h($v)?></option><?php endforeach;?></select><button name="update_status">Update status</button></form><?php endif;?></article><?php endforeach;?><?php page_end();
